export interface UserRow { id: number; name: string }

export function usersGateway(pool: Pool) {
  return {
    insert: (u: UserRow) =>
      pool.query('INSERT INTO users(id, name) VALUES($1, $2)', [u.id, u.name]),
    find: async (id: number): Promise<UserRow | undefined> =>
      (await pool.query<UserRow>(
        'SELECT id, name FROM users WHERE id = $1', [id])).rows[0],
  };
}

